# ClearLedger Runtime and Application Contract

All four application images are pre-built and loaded into the local container daemon. Do not rebuild or modify the application binaries. Configure each runtime using the environment variables below.

## 1. API Service (`api_image` on ECS Fargate)

- **Binary**: `/usr/local/bin/clearledger-api`
- **Listening port**: `8080` (`PORT=8080`)
- **Required environment variables**:
  - `PORT`: `"8080"`
  - `AWS_REGION`: region from `config.json` (`us-east-1`)
  - `AWS_DEFAULT_REGION`: region from `config.json` (`us-east-1`)
  - `AWS_ACCESS_KEY_ID`: `"test"`
  - `AWS_SECRET_ACCESS_KEY`: `"test"`
  - `AWS_ENDPOINT_URL`: control-plane endpoint reachable from the container (`http://aws:4566`)
  - `DATABASE_URL`: PostgreSQL connection string `postgres://<db_username>:<db_password>@<rds_host>:<rds_port>/<db_name>`
  - `SQS_QUEUE_URL`: URL of the main SQS event queue
  - `PROJECTION_TABLE`: name of the DynamoDB projection table
  - `VALKEY_URL`: Valkey connection URL `redis://<valkey_host>:<valkey_port>`
  - `CACHE_TTL_SECONDS`: `"90"` (must be explicitly set to `"90"`)
  - `AUTH_ISSUER`: Cognito issuer URL (`http://aws:4566/<user_pool_id>`)
  - `AUTH_AUDIENCES`: comma-separated Cognito client IDs (`<read_client_id>,<write_client_id>,<admin_client_id>`)
  - `AUTH_JWKS_URL`: Cognito JWKS URL (`http://aws:4566/<user_pool_id>/.well-known/jwks.json`)
  - `CLOUDWATCH_LOG_GROUP`: name of the API CloudWatch Log Group
  - `SERVICE_INSTANCE_ID` (optional): instance identifier returned in `X-ClearLedger-Instance` (defaults to `HOSTNAME`)

Upon startup, `clearledger-api` connects to PostgreSQL and serves HTTP traffic on `0.0.0.0:8080`. The application binaries do **not** run database migrations automatically: `deploy.sh` must idempotently apply the `clearledger` PostgreSQL schema (`clearledger.settlements`, `clearledger.events`, `clearledger.outbox`, `clearledger.idempotency_keys`), all required relational `CHECK` / `UNIQUE` / `FOREIGN KEY` constraints, all state-transition, cross-table, and append-only triggers across all four tables, and its three indexes as defined in `services/rds.md` before `GET /health/ready` reports `200 OK` (`checks.postgres = "UP"`). During `POST /v1/settlements` and `POST /v1/settlements/{id}/entries`, `clearledger-api` maps PostgreSQL constraint and trigger exceptions (`SQLSTATE 23514`, `23503`, `23502`, `23505`, and `P0001`) to HTTP `400 Bad Request` (`invalid_settlement`).

## 2. Projector Worker (`projector_image` on AWS Lambda)

- **Bootstrap**: `/var/runtime/bootstrap`
- **Trigger**: SQS event source mapping from the main SQS queue (`batch_size = 5`, `maximum_batching_window_in_seconds = 0`, `function_response_types = ["ReportBatchItemFailures"]`)
- **Required environment variables**:
  - `AWS_REGION`: region from `config.json`
  - `AWS_DEFAULT_REGION`: region from `config.json`
  - `AWS_ACCESS_KEY_ID`: `"test"`
  - `AWS_SECRET_ACCESS_KEY`: `"test"`
  - `AWS_ENDPOINT_URL`: `"http://aws:4566"`

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://clearledger.internal/schemas/manifest.schema.json",
  "title": "ClearLedgerSubmissionManifest",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "resource_prefix",
    "region",
    "service_url",
    "network",
    "ingress",
    "compute",
    "database",
    "messaging",
    "workers",
    "projections",
    "cache",
    "audit",
    "schedules",
    "auth",
    "iam",
    "kms",
    "logs"
  ],
  "properties": {
    "resource_prefix": { "type": "string", "minLength": 4 },
    "region": { "type": "string", "const": "us-east-1" },
    "service_url": { "type": "string", "pattern": "^http://" },
    "network": {
      "type": "object",
      "additionalProperties": false,
      "required": ["vpc_id", "public_subnet_ids", "private_subnet_ids", "security_group_ids"],
      "properties": {
        "vpc_id": { "type": "string", "minLength": 4 },
        "public_subnet_ids": {
          "type": "array",
          "minItems": 2,
          "uniqueItems": true,
          "items": { "type": "string", "minLength": 4 }
        },
        "private_subnet_ids": {
          "type": "array",
          "minItems": 2,
          "uniqueItems": true,
          "items": { "type": "string", "minLength": 4 }
        },
        "security_group_ids": {
          "type": "object",
          "additionalProperties": false,
          "required": ["alb", "ecs", "rds", "valkey"],
          "properties": {
            "alb": { "type": "string", "minLength": 4 },
            "ecs": { "type": "string", "minLength": 4 },
            "rds": { "type": "string", "minLength": 4 },
            "valkey": { "type": "string", "minLength": 4 }
          }
        }
      }
    },
    "ingress": {
      "type": "object",
      "additionalProperties": false,
      "required": ["alb_arn", "alb_dns_name", "listener_arn", "target_group_arn", "container_port"],
      "properties": {
        "alb_arn": { "type": "string", "minLength": 8 },
        "alb_dns_name": { "type": "string", "minLength": 3 },
        "listener_arn": { "type": "string", "minLength": 8 },
        "target_group_arn": { "type": "string", "minLength": 8 },
        "container_port": { "type": "integer", "const": 8080 }
      }
    },
    "compute": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "cluster_arn",
        "cluster_name",
        "service_arn",
        "service_name",
        "task_definition_arn",
        "desired_count"
      ],
      "properties": {
        "cluster_arn": { "type": "string", "minLength": 8 },
        "cluster_name": { "type": "string", "minLength": 4 },
        "service_arn": { "type": "string", "minLength": 8 },
        "service_name": { "type": "string", "minLength": 4 },
        "task_definition_arn": { "type": "string", "minLength": 8 },
        "desired_count": { "type": "integer", "minimum": 2 }
      }
    },
    "database": {
      "type": "object",
      "additionalProperties": false,
      "required": ["instance_id", "instance_arn", "endpoint", "port", "db_name", "username"],
      "properties": {
        "instance_id": { "type": "string", "minLength": 4 },
        "instance_arn": { "type": "string", "minLength": 8 },
        "endpoint": { "type": "string", "minLength": 3 },
        "port": { "type": "integer", "minimum": 1 },
        "db_name": { "type": "string", "minLength": 3 },
        "username": { "type": "string", "minLength": 3 }
      }
    },
    "messaging": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "queue_name",
        "queue_url",
        "queue_arn",
        "dlq_name",
        "dlq_url",
        "dlq_arn",
        "event_source_mapping_uuid",
        "max_receive_count"
      ],
      "properties": {
        "queue_name": { "type": "string", "minLength": 4 },
        "queue_url": { "type": "string", "pattern": "^http" },
        "queue_arn": { "type": "string", "minLength": 8 },
        "dlq_name": { "type": "string", "minLength": 4 },
        "dlq_url": { "type": "string", "pattern": "^http" },
        "dlq_arn": { "type": "string", "minLength": 8 },
        "event_source_mapping_uuid": { "type": "string", "minLength": 4 },
        "max_receive_count": { "type": "integer", "const": 4 }
      }
    },
    "workers": {
      "type": "object",
      "additionalProperties": false,
      "required": ["projector", "outbox_relay", "audit_archiver"],
      "properties": {
        "projector": {
          "type": "object",
          "additionalProperties": false,
          "required": ["function_name", "function_arn"],
          "properties": {
            "function_name": { "type": "string", "minLength": 4 },
            "function_arn": { "type": "string", "minLength": 8 }
          }
        },
        "outbox_relay": {
          "type": "object",
          "additionalProperties": false,
          "required": ["function_name", "function_arn"],
          "properties": {
            "function_name": { "type": "string", "minLength": 4 },
            "function_arn": { "type": "string", "minLength": 8 }
          }
        },
        "audit_archiver": {
          "type": "object",
          "additionalProperties": false,
          "required": ["function_name", "function_arn"],
          "properties": {
            "function_name": { "type": "string", "minLength": 4 },
            "function_arn": { "type": "string", "minLength": 8 }
          }
        }
      }
    },
    "projections": {
      "type": "object",
      "additionalProperties": false,
      "required": ["table_name", "table_arn", "gsi_name"],
      "properties": {
        "table_name": { "type": "string", "minLength": 4 },
        "table_arn": { "type": "string", "minLength": 8 },
        "gsi_name": { "type": "string", "const": "AccountIndex" }
      }
    },
    "cache": {
      "type": "object",
      "additionalProperties": false,
      "required": ["cluster_id", "engine", "endpoint", "port"],
      "properties": {
        "cluster_id": { "type": "string", "minLength": 4 },
        "engine": { "type": "string", "enum": ["valkey", "redis"] },
        "endpoint": { "type": "string", "minLength": 3 },
        "port": { "type": "integer", "minimum": 1 }
      }
    },
    "audit": {
      "type": "object",
      "additionalProperties": false,
      "required": ["bucket_name", "bucket_arn", "prefix"],
      "properties": {
        "bucket_name": { "type": "string", "minLength": 4 },
        "bucket_arn": { "type": "string", "minLength": 8 },
        "prefix": { "type": "string", "const": "ledger-audit/" }
      }
    },
    "schedules": {
      "type": "object",
      "additionalProperties": false,
      "required": ["outbox_schedule_name", "outbox_schedule_arn", "archive_schedule_name", "archive_schedule_arn"],
      "properties": {
        "outbox_schedule_name": { "type": "string", "minLength": 4 },
        "outbox_schedule_arn": { "type": "string", "minLength": 8 },
        "archive_schedule_name": { "type": "string", "minLength": 4 },
        "archive_schedule_arn": { "type": "string", "minLength": 8 }
      }
    },
    "auth": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "user_pool_id",
        "user_pool_arn",
        "issuer_url",
        "token_endpoint",
        "resource_server_identifier",
        "clients"
      ],
      "properties": {
        "user_pool_id": { "type": "string", "minLength": 4 },
        "user_pool_arn": { "type": "string", "minLength": 8 },
        "issuer_url": { "type": "string", "pattern": "^http" },
        "token_endpoint": { "type": "string", "pattern": "^http" },
        "resource_server_identifier": { "type": "string", "const": "clearledger" },
        "clients": {
          "type": "object",
          "additionalProperties": false,
          "required": ["read", "write", "admin"],
          "properties": {
            "read": {
              "type": "object",
              "additionalProperties": false,
              "required": ["client_id", "client_secret", "scope"],
              "properties": {
                "client_id": { "type": "string", "minLength": 4 },
                "client_secret": { "type": "string", "minLength": 4 },
                "scope": { "type": "string", "const": "clearledger/read" }
              }
            },
            "write": {
              "type": "object",
              "additionalProperties": false,
              "required": ["client_id", "client_secret", "scope"],
              "properties": {
                "client_id": { "type": "string", "minLength": 4 },
                "client_secret": { "type": "string", "minLength": 4 },
                "scope": { "type": "string", "const": "clearledger/write" }
              }
            },
            "admin": {
              "type": "object",
              "additionalProperties": false,
              "required": ["client_id", "client_secret", "scope"],
              "properties": {
                "client_id": { "type": "string", "minLength": 4 },
                "client_secret": { "type": "string", "minLength": 4 },
                "scope": { "type": "string", "const": "clearledger/admin" }
              }
            }
          }
        }
      }
    },
    "iam": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ecs_execution_role_arn",
        "ecs_task_role_arn",
        "projector_role_arn",
        "relay_role_arn",
        "archiver_role_arn",
        "scheduler_role_arn"
      ],
      "properties": {
        "ecs_execution_role_arn": { "type": "string", "minLength": 8 },
        "ecs_task_role_arn": { "type": "string", "minLength": 8 },
        "projector_role_arn": { "type": "string", "minLength": 8 },
        "relay_role_arn": { "type": "string", "minLength": 8 },
        "archiver_role_arn": { "type": "string", "minLength": 8 },
        "scheduler_role_arn": { "type": "string", "minLength": 8 }
      }
    },
    "kms": {
      "type": "object",
      "additionalProperties": false,
      "required": ["database_arn", "messaging_arn", "projection_arn", "audit_arn"],
      "properties": {
        "database_arn": { "type": "string", "minLength": 8 },
        "messaging_arn": { "type": "string", "minLength": 8 },
        "projection_arn": { "type": "string", "minLength": 8 },
        "audit_arn": { "type": "string", "minLength": 8 }
      }
    },
    "logs": {
      "type": "object",
      "additionalProperties": false,
      "required": ["api_log_group", "projector_log_group", "relay_log_group", "archiver_log_group"],
      "properties": {
        "api_log_group": { "type": "string", "minLength": 4 },
        "projector_log_group": { "type": "string", "minLength": 4 },
        "relay_log_group": { "type": "string", "minLength": 4 },
        "archiver_log_group": { "type": "string", "minLength": 4 }
      }
    }
  }
}
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://clearledger.internal/schemas/events.schema.json",
  "title": "ClearLedgerDomainEventEnvelope",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schemaVersion",
    "eventId",
    "eventType",
    "aggregateType",
    "aggregateId",
    "aggregateVersion",
    "occurredAt",
    "correlationId",
    "idempotencyKey",
    "data"
  ],
  "properties": {
    "schemaVersion": {
      "type": "string",
      "const": "1.0"
    },
    "eventId": {
      "type": "string",
      "format": "uuid"
    },
    "eventType": {
      "type": "string",
      "enum": ["SettlementInitiated", "LedgerEntryRecorded"]
    },
    "aggregateType": {
      "type": "string",
      "const": "settlement"
    },
    "aggregateId": {
      "type": "string",
      "format": "uuid"
    },
    "aggregateVersion": {
      "type": "integer",
      "minimum": 1
    },
    "occurredAt": {
      "type": "string",
      "format": "date-time"
    },
    "correlationId": {
      "type": "string",
      "minLength": 4
    },
    "idempotencyKey": {
      "type": "string",
      "minLength": 8
    },
    "data": {
      "type": "object",
      "required": ["kind", "accountId", "status", "clearingStage"],
      "properties": {
        "kind": {
          "type": "string",
          "enum": ["settlementInitiated", "ledgerEntryRecorded"]
        },
        "accountId": {
          "type": "string",
          "minLength": 3
        },
        "reference": {
          "type": "string"
        },
        "debitParty": {
          "type": "string"
        },
        "creditParty": {
          "type": "string"
        },
        "entryId": {
          "type": ["string", "null"],
          "format": "uuid"
        },
        "status": {
          "type": "string",
          "enum": [
            "INITIATED",
            "VALIDATED",
            "RESERVED",
            "CLEARED",
            "SETTLED",
            "RECONCILED",
            "DISPUTED"
          ]
        },
        "clearingStage": {
          "type": "string",
          "minLength": 2
        },
        "memo": {
          "type": ["string", "null"]
        }
      },
      "additionalProperties": false
    }
  }
}

provider_installation {
  filesystem_mirror {
    path    = "/opt/Terraform/cache"
    include = ["registry.terraform.io/hashicorp/*", "registry.opentofu.org/hashicorp/*"]
  }
  direct {
    exclude = ["registry.terraform.io/hashicorp/*", "registry.opentofu.org/hashicorp/*"]
  }
}
disable_checkpoint = true
