arguments.content:
terraform {
  required_version = ">= 1.6.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }

  backend "local" {
    path = "terraform.tfstate"
  }
}

provider "aws" {
  region                      = var.region
  access_key                  = "test"
  secret_key                  = "test"
  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = false
  skip_region_validation      = true
  s3_use_path_style           = true

  endpoints {
    acm              = var.aws_endpoint_url
    cloudwatch       = var.aws_endpoint_url
    cloudwatchlogs   = var.aws_endpoint_url
    cognitoidp       = var.aws_endpoint_url
    dynamodb         = var.aws_endpoint_url
    ec2              = var.aws_endpoint_url
    ecs              = var.aws_endpoint_url
    elasticache      = var.aws_endpoint_url
    elbv2            = var.aws_endpoint_url
    iam              = var.aws_endpoint_url
    kms              = var.aws_endpoint_url
    lambda           = var.aws_endpoint_url
    rds              = var.aws_endpoint_url
    s3               = var.aws_endpoint_url
    scheduler        = var.aws_endpoint_url
    sqs              = var.aws_endpoint_url
    sts              = var.aws_endpoint_url
    resourcegroupstaggingapi = var.aws_endpoint_url
  }

  default_tags {
    tags = {
      ClearLedgerDeployment = var.resource_prefix
      Project               = "clearledger"
    }
  }
}

variable "resource_prefix" {
  type = string
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "aws_endpoint_url" {
  type    = string
  default = "http://aws:4566"
}

variable "db_name" {
  type = string
}

variable "db_username" {
  type = string
}

variable "db_password" {
  type      = string
  sensitive = true
}

variable "api_image" {
  type = string
}

variable "projector_image" {
  type = string
}

variable "relay_image" {
  type = string
}

variable "archiver_image" {
  type = string
}

variable "api_image_id" {
  type    = string
  default = ""
}

variable "projector_image_id" {
  type    = string
  default = ""
}

variable "relay_image_id" {
  type    = string
  default = ""
}

variable "archiver_image_id" {
  type    = string
  default = ""
}

variable "vpc_cidr" {
  type    = string
  default = "10.42.0.0/16"
}

variable "cache_ttl_seconds" {
  type    = string
  default = "90"
}

variable "outbox_batch_size" {
  type    = string
  default = "50"
}

variable "audit_prefix" {
  type    = string
  default = "ledger-audit/"
}

locals {
  p          = var.resource_prefix
  account_id = data.aws_caller_identity.current.account_id
  azs        = ["${var.region}a", "${var.region}b"]

  log_groups = {
    api       = "/clearledger/${local.p}/api"
    projector = "/clearledger/${local.p}/projector"
    relay     = "/clearledger/${local.p}/outbox-relay"
    archiver  = "/clearledger/${local.p}/audit-archiver"
  }

  common_lambda_env = {
    AWS_REGION            = var.region
    AWS_DEFAULT_REGION    = var.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = var.aws_endpoint_url
  }

  database_url = "postgres://${urlencode(var.db_username)}:${urlencode(var.db_password)}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${var.db_name}"
  valkey_url   = "redis://${aws_elasticache_replication_group.cache.primary_endpoint_address}:${aws_elasticache_replication_group.cache.port}"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = { Name = "${local.p}-vpc" }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = true

  tags = { Name = "${local.p}-public-${local.azs[count.index]}", Tier = "public" }
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = { Name = "${local.p}-private-${local.azs[count.index]}", Tier = "private" }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.p}-igw" }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = { Name = "${local.p}-public-rt" }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "${local.p}-private-rt" }
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security groups use inline (authoritative) rule blocks so that any
# out-of-band rule added to a group is removed on the next apply.

resource "aws_security_group" "alb" {
  name        = "${local.p}-alb"
  description = "ClearLedger ALB - HTTP in from internet, 8080 out to ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward to API tasks"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = { Name = "${local.p}-alb" }
}

resource "aws_security_group" "ecs" {
  name        = "${local.p}-ecs"
  description = "ClearLedger API tasks - 8080 from ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API traffic from ALB"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "AWS control plane and data stores"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = { Name = "${local.p}-ecs" }
}

resource "aws_security_group" "rds" {
  name        = "${local.p}-rds"
  description = "ClearLedger PostgreSQL - 5432 from ECS tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    description = "Intra-VPC only"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = { Name = "${local.p}-rds" }
}

resource "aws_security_group" "valkey" {
  name        = "${local.p}-valkey"
  description = "ClearLedger Valkey - 6379 from ECS tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress {
    description = "Intra-VPC only"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = { Name = "${local.p}-valkey" }
}

locals {
  kms_purposes = {
    database   = "ClearLedger RDS PostgreSQL storage encryption"
    messaging  = "ClearLedger SQS main queue and DLQ encryption"
    projection = "ClearLedger DynamoDB projection table encryption"
    audit      = "ClearLedger S3 audit archive encryption"
  }
}

resource "aws_kms_key" "this" {
  for_each = local.kms_purposes

  description             = "${local.p}-${each.key}: ${each.value}"
  enable_key_rotation     = true
  deletion_window_in_days = 10

  tags = { Name = "${local.p}-${each.key}", Purpose = each.key }
}

resource "aws_kms_alias" "this" {
  for_each = local.kms_purposes

  name          = "alias/${local.p}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}

resource "aws_cloudwatch_log_group" "this" {
  for_each = local.log_groups

  name              = each.value
  retention_in_days = 14

  tags = { Name = "${local.p}-${each.key}-logs", Workload = each.key }
}

############################
# RDS PostgreSQL
############################

resource "aws_db_subnet_group" "main" {
  name       = "${local.p}-db-subnets"
  subnet_ids = aws_subnet.private[*].id

  tags = { Name = "${local.p}-db-subnets" }
}

resource "aws_db_instance" "main" {
  identifier             = "${local.p}-postgres"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  storage_type           = "gp3"
  db_name                = var.db_name
  username               = var.db_username
  password               = var.db_password
  port                   = 5432
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  deletion_protection    = false
  apply_immediately      = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]

  tags = { Name = "${local.p}-postgres" }

  lifecycle {
    # Never replace the system of record because of cosmetic drift.
    ignore_changes = [engine_version, allocated_storage, storage_type]
  }
}

############################
# DynamoDB projection store
############################

resource "aws_dynamodb_table" "projections" {
  name         = "${local.p}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }

  attribute {
    name = "SK"
    type = "S"
  }

  attribute {
    name = "GSI1PK"
    type = "S"
  }

  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = { Name = "${local.p}-projections" }
}

############################
# ElastiCache for Valkey
############################

resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.p}-cache-subnets"
  subnet_ids = aws_subnet.private[*].id

  tags = { Name = "${local.p}-cache-subnets" }
}

resource "aws_elasticache_replication_group" "cache" {
  replication_group_id       = "${local.p}-valkey"
  description                = "ClearLedger projection cache (${local.p})"
  engine                     = "valkey"
  engine_version             = "8.0"
  node_type                  = "cache.t4g.micro"
  num_cache_clusters         = 1
  port                       = 6379
  subnet_group_name          = aws_elasticache_subnet_group.main.name
  security_group_ids         = [aws_security_group.valkey.id]
  automatic_failover_enabled = false
  apply_immediately          = true
  transit_encryption_enabled = false
  at_rest_encryption_enabled = false

  tags = { Name = "${local.p}-valkey" }
}

############################
# S3 audit archive
############################

resource "aws_s3_bucket" "audit" {
  bucket        = "${local.p}-audit-archive"
  force_destroy = true

  tags = { Name = "${local.p}-audit-archive" }
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

############################
# SQS main queue + DLQ
############################

resource "aws_sqs_queue" "dlq" {
  name                              = "${local.p}-events-dlq"
  kms_master_key_id                 = aws_kms_key.this["messaging"].arn
  kms_data_key_reuse_period_seconds = 300
  message_retention_seconds         = 1209600

  tags = { Name = "${local.p}-events-dlq" }
}

resource "aws_sqs_queue" "main" {
  name                              = "${local.p}-events"
  kms_master_key_id                 = aws_kms_key.this["messaging"].arn
  kms_data_key_reuse_period_seconds = 300
  visibility_timeout_seconds        = 3
  receive_wait_time_seconds         = 2
  message_retention_seconds         = 172800

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })

  tags = { Name = "${local.p}-events" }
}

resource "aws_cognito_user_pool" "main" {
  name = "${local.p}-users"

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  tags = { Name = "${local.p}-users" }
}

resource "aws_cognito_resource_server" "clearledger" {
  user_pool_id = aws_cognito_user_pool.main.id
  identifier   = "clearledger"
  name         = "${local.p}-clearledger-api"

  scope {
    scope_name        = "read"
    scope_description = "Read settlement projections and ledgers"
  }

  scope {
    scope_name        = "write"
    scope_description = "Initiate settlements and append ledger entries"
  }

  scope {
    scope_name        = "admin"
    scope_description = "Rebuild settlement projections"
  }
}

locals {
  cognito_clients = ["read", "write", "admin"]
}

resource "aws_cognito_user_pool_client" "this" {
  for_each = toset(local.cognito_clients)

  name                                 = "${local.p}-${each.key}"
  user_pool_id                         = aws_cognito_user_pool.main.id
  generate_secret                      = true
  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["client_credentials"]
  allowed_oauth_scopes                 = ["clearledger/${each.key}"]
  supported_identity_providers         = ["COGNITO"]
  explicit_auth_flows                  = ["ALLOW_REFRESH_TOKEN_AUTH"]

  depends_on = [aws_cognito_resource_server.clearledger]
}

locals {
  queue_arn = aws_sqs_queue.main.arn
  dlq_arn   = aws_sqs_queue.dlq.arn
  table_arn = aws_dynamodb_table.projections.arn
  gsi_arn   = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  bucket    = aws_s3_bucket.audit.arn
  kms       = { for k, v in aws_kms_key.this : k => v.arn }

  log_arn = {
    for k, name in local.log_groups :
    k => "arn:aws:logs:${var.region}:${local.account_id}:log-group:${name}"
  }
  log_res = { for k, a in local.log_arn : k => [a, "${a}:*"] }

  log_write_actions = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  log_deny_actions  = ["logs:CreateLogStream", "logs:PutLogEvents"]

  # ---- reusable explicit Deny guardrails ----
  deny_sqs_all = {
    Sid      = "DenySqsAccess"
    Effect   = "Deny"
    Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
    Resource = [local.queue_arn, local.dlq_arn]
  }
  deny_ddb_all = {
    Sid      = "DenyDynamoDbAccess"
    Effect   = "Deny"
    Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
    Resource = [local.table_arn, local.gsi_arn]
  }
  deny_s3_all = {
    Sid      = "DenyAuditBucketAccess"
    Effect   = "Deny"
    Action   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
    Resource = [local.bucket, "${local.bucket}/*"]
  }

  lambda_trust = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  ecs_trust = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "ecs-tasks.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  scheduler_trust = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "scheduler.amazonaws.com" }
      Action    = "sts:AssumeRole"
      Condition = { StringEquals = { "aws:SourceAccount" = local.account_id } }
    }]
  })
}

############################
# Roles
############################

resource "aws_iam_role" "ecs_execution" {
  name                 = "${local.p}-ecs-execution"
  description          = "ClearLedger ECS task execution role (log shipping only)"
  assume_role_policy   = local.ecs_trust
  max_session_duration = 3600
  tags                 = { Name = "${local.p}-ecs-execution" }
}

resource "aws_iam_role" "ecs_task" {
  name               = "${local.p}-ecs-task"
  description        = "ClearLedger API task role"
  assume_role_policy = local.ecs_trust
  tags               = { Name = "${local.p}-ecs-task" }
}

resource "aws_iam_role" "projector" {
  name               = "${local.p}-projector"
  description        = "ClearLedger projector Lambda role"
  assume_role_policy = local.lambda_trust
  tags               = { Name = "${local.p}-projector" }
}

resource "aws_iam_role" "relay" {
  name               = "${local.p}-relay"
  description        = "ClearLedger outbox relay Lambda role"
  assume_role_policy = local.lambda_trust
  tags               = { Name = "${local.p}-relay" }
}

resource "aws_iam_role" "archiver" {
  name               = "${local.p}-archiver"
  description        = "ClearLedger audit archiver Lambda role"
  assume_role_policy = local.lambda_trust
  tags               = { Name = "${local.p}-archiver" }
}

resource "aws_iam_role" "scheduler" {
  name               = "${local.p}-scheduler"
  description        = "ClearLedger EventBridge Scheduler invocation role"
  assume_role_policy = local.scheduler_trust
  tags               = { Name = "${local.p}-scheduler" }
}

############################
# Policies
############################

resource "aws_iam_role_policy" "ecs_execution" {
  name = "${local.p}-ecs-execution-policy"
  role = aws_iam_role.ecs_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ApiLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_res["api"]
      },
      local.deny_sqs_all,
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyAllClearLedgerKmsKeys"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = values(local.kms)
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = concat(local.log_res["projector"], local.log_res["relay"], local.log_res["archiver"])
      },
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task" {
  name = "${local.p}-ecs-task-policy"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "ReadProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms["messaging"], local.kms["projection"]]
      },
      {
        Sid      = "ApiLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_res["api"]
      },
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyDlqAccess"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionMutation"
        Effect   = "Deny"
        Action   = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      local.deny_s3_all,
      {
        Sid      = "DenyDatabaseAndAuditKeys"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [local.kms["database"], local.kms["audit"]]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = concat(local.log_res["projector"], local.log_res["relay"], local.log_res["archiver"])
      },
    ]
  })
}

resource "aws_iam_role_policy" "projector" {
  name = "${local.p}-projector-policy"
  role = aws_iam_role.projector.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ConsumeMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "ForwardToDlq"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "UpsertProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      {
        Sid      = "UseMessagingAndProjectionKeys"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms["messaging"], local.kms["projection"]]
      },
      {
        Sid      = "ProjectorLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_res["projector"]
      },
      {
        Sid      = "DenyPublishMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyConsumeDlq"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyProjectionDeletes"
        Effect   = "Deny"
        Action   = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn, local.gsi_arn]
      },
      local.deny_s3_all,
      {
        Sid      = "DenyDatabaseAndAuditKeys"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [local.kms["database"], local.kms["audit"]]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = concat(local.log_res["api"], local.log_res["relay"], local.log_res["archiver"])
      },
    ]
  })
}

resource "aws_iam_role_policy" "relay" {
  name = "${local.p}-relay-policy"
  role = aws_iam_role.relay.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "UseMessagingAndDatabaseKeys"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms["messaging"], local.kms["database"]]
      },
      {
        Sid      = "RelayLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_res["relay"]
      },
      {
        Sid      = "DenyConsumeMainQueue"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.queue_arn]
      },
      {
        Sid      = "DenyDlqAccess"
        Effect   = "Deny"
        Action   = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.dlq_arn]
      },
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyProjectionAndAuditKeys"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [local.kms["projection"], local.kms["audit"]]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = concat(local.log_res["api"], local.log_res["projector"], local.log_res["archiver"])
      },
    ]
  })
}

resource "aws_iam_role_policy" "archiver" {
  name = "${local.p}-archiver-policy"
  role = aws_iam_role.archiver.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AppendAuditObjects"
        Effect   = "Allow"
        Action   = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"]
        Resource = ["${local.bucket}/ledger-audit/*"]
      },
      {
        Sid      = "AuditBucketMetadata"
        Effect   = "Allow"
        Action   = ["s3:ListBucket", "s3:GetBucketLocation"]
        Resource = [local.bucket]
      },
      {
        Sid      = "UseAuditAndDatabaseKeys"
        Effect   = "Allow"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
        Resource = [local.kms["audit"], local.kms["database"]]
      },
      {
        Sid      = "ArchiverLogWrite"
        Effect   = "Allow"
        Action   = local.log_write_actions
        Resource = local.log_res["archiver"]
      },
      {
        Sid      = "DenyAuditDeletes"
        Effect   = "Deny"
        Action   = ["s3:DeleteObject", "s3:DeleteObjectVersion"]
        Resource = [local.bucket, "${local.bucket}/*"]
      },
      local.deny_sqs_all,
      local.deny_ddb_all,
      {
        Sid      = "DenyMessagingAndProjectionKeys"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = [local.kms["messaging"], local.kms["projection"]]
      },
      {
        Sid      = "DenyForeignLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = concat(local.log_res["api"], local.log_res["projector"], local.log_res["relay"])
      },
    ]
  })
}

resource "aws_iam_role_policy" "scheduler" {
  name = "${local.p}-scheduler-policy"
  role = aws_iam_role.scheduler.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "InvokeScheduledWorkers"
        Effect   = "Allow"
        Action   = ["lambda:InvokeFunction"]
        Resource = [aws_lambda_function.relay.arn, aws_lambda_function.archiver.arn]
      },
      {
        Sid      = "DenyInvokeProjector"
        Effect   = "Deny"
        Action   = ["lambda:InvokeFunction"]
        Resource = [aws_lambda_function.projector.arn]
      },
      local.deny_sqs_all,
      local.deny_ddb_all,
      local.deny_s3_all,
      {
        Sid      = "DenyAllClearLedgerKmsKeys"
        Effect   = "Deny"
        Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
        Resource = values(local.kms)
      },
      {
        Sid      = "DenyAllClearLedgerLogGroups"
        Effect   = "Deny"
        Action   = local.log_deny_actions
        Resource = flatten(values(local.log_res))
      },
    ]
  })
}

# Authoritative policy sets: any inline policy or managed-policy attachment
# added to a ClearLedger workload role outside Terraform is removed on apply.

locals {
  workload_roles = {
    ecs_execution = { role = aws_iam_role.ecs_execution.name, policy = aws_iam_role_policy.ecs_execution.name }
    ecs_task      = { role = aws_iam_role.ecs_task.name, policy = aws_iam_role_policy.ecs_task.name }
    projector     = { role = aws_iam_role.projector.name, policy = aws_iam_role_policy.projector.name }
    relay         = { role = aws_iam_role.relay.name, policy = aws_iam_role_policy.relay.name }
    archiver      = { role = aws_iam_role.archiver.name, policy = aws_iam_role_policy.archiver.name }
    scheduler     = { role = aws_iam_role.scheduler.name, policy = aws_iam_role_policy.scheduler.name }
  }
}

resource "aws_iam_role_policies_exclusive" "this" {
  for_each = local.workload_roles

  role_name    = each.value.role
  policy_names = [each.value.policy]
}

resource "aws_iam_role_policy_attachments_exclusive" "this" {
  for_each = local.workload_roles

  role_name   = each.value.role
  policy_arns = []
}

############################
# Application Load Balancer
############################

resource "aws_lb" "api" {
  name               = "${local.p}-alb"
  load_balancer_type = "application"
  internal           = false
  subnets            = aws_subnet.public[*].id
  security_groups    = [aws_security_group.alb.id]
  idle_timeout       = 60

  tags = { Name = "${local.p}-alb" }
}

resource "aws_lb_target_group" "api" {
  name                 = "${local.p}-api-tg"
  port                 = 8080
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 10

  health_check {
    enabled             = true
    path                = "/health/ready"
    protocol            = "HTTP"
    port                = "traffic-port"
    matcher             = "200"
    interval            = 10
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 3
  }

  tags = { Name = "${local.p}-api-tg" }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.api.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.api.arn
  }

  tags = { Name = "${local.p}-http" }
}

############################
# ECS Fargate API service
############################

resource "aws_ecs_cluster" "main" {
  name = "${local.p}-cluster"

  setting {
    name  = "containerInsights"
    value = "enabled"
  }

  tags = { Name = "${local.p}-cluster" }
}

locals {
  auth_issuer   = "${var.aws_endpoint_url}/${aws_cognito_user_pool.main.id}"
  auth_jwks_url = "${var.aws_endpoint_url}/${aws_cognito_user_pool.main.id}/.well-known/jwks.json"
  auth_audiences = join(",", [
    aws_cognito_user_pool_client.this["read"].id,
    aws_cognito_user_pool_client.this["write"].id,
    aws_cognito_user_pool_client.this["admin"].id,
  ])

  api_env = {
    PORT                  = "8080"
    AWS_REGION            = var.region
    AWS_DEFAULT_REGION    = var.region
    AWS_ACCESS_KEY_ID     = "test"
    AWS_SECRET_ACCESS_KEY = "test"
    AWS_ENDPOINT_URL      = var.aws_endpoint_url
    DATABASE_URL          = local.database_url
    SQS_QUEUE_URL         = aws_sqs_queue.main.url
    PROJECTION_TABLE      = aws_dynamodb_table.projections.name
    VALKEY_URL            = local.valkey_url
    CACHE_TTL_SECONDS     = var.cache_ttl_seconds
    AUTH_ISSUER           = local.auth_issuer
    AUTH_AUDIENCES        = local.auth_audiences
    AUTH_JWKS_URL         = local.auth_jwks_url
    CLOUDWATCH_LOG_GROUP  = aws_cloudwatch_log_group.this["api"].name
  }
}

resource "aws_ecs_task_definition" "api" {
  family                   = "${local.p}-api"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = "512"
  memory                   = "1024"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "api"
      image     = var.api_image
      essential = true
      portMappings = [
        {
          containerPort = 8080
          hostPort      = 8080
          protocol      = "tcp"
        }
      ]
      environment = [for k in sort(keys(local.api_env)) : { name = k, value = local.api_env[k] }]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          awslogs-group         = aws_cloudwatch_log_group.this["api"].name
          awslogs-region        = var.region
          awslogs-stream-prefix = "api"
        }
      }
    }
  ])

  tags = { Name = "${local.p}-api", ImageId = var.api_image_id }
}

resource "aws_ecs_service" "api" {
  name                               = "${local.p}-api"
  cluster                            = aws_ecs_cluster.main.id
  task_definition                    = aws_ecs_task_definition.api.arn
  launch_type                        = "FARGATE"
  desired_count                      = 2
  health_check_grace_period_seconds  = 30
  deployment_minimum_healthy_percent = 100
  deployment_maximum_percent         = 200

  network_configuration {
    subnets          = aws_subnet.private[*].id
    security_groups  = [aws_security_group.ecs.id]
    assign_public_ip = false
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.api.arn
    container_name   = "api"
    container_port   = 8080
  }

  tags = { Name = "${local.p}-api" }

  depends_on = [aws_lb_listener.http, aws_iam_role_policy.ecs_execution, aws_iam_role_policy.ecs_task]
}

############################
# Lambda workers
############################

resource "aws_lambda_function" "projector" {
  function_name = "${local.p}-projector"
  description   = "ClearLedger projector (SQS -> DynamoDB/Valkey)"
  package_type  = "Image"
  image_uri     = var.projector_image
  role          = aws_iam_role.projector.arn
  timeout       = 3
  memory_size   = 512

  environment {
    variables = merge(local.common_lambda_env, {
      PROJECTION_TABLE     = aws_dynamodb_table.projections.name
      VALKEY_URL           = local.valkey_url
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["projector"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["projector"].name
  }

  tags = { Name = "${local.p}-projector", ImageId = var.projector_image_id }

  depends_on = [aws_iam_role_policy.projector]
}

resource "aws_lambda_function" "relay" {
  function_name = "${local.p}-outbox-relay"
  description   = "ClearLedger outbox relay (PostgreSQL outbox -> SQS)"
  package_type  = "Image"
  image_uri     = var.relay_image
  role          = aws_iam_role.relay.arn
  timeout       = 60
  memory_size   = 512

  environment {
    variables = merge(local.common_lambda_env, {
      DATABASE_URL         = local.database_url
      SQS_QUEUE_URL        = aws_sqs_queue.main.url
      OUTBOX_BATCH_SIZE    = var.outbox_batch_size
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["relay"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["relay"].name
  }

  tags = { Name = "${local.p}-outbox-relay", ImageId = var.relay_image_id }

  depends_on = [aws_iam_role_policy.relay]
}

resource "aws_lambda_function" "archiver" {
  function_name = "${local.p}-audit-archiver"
  description   = "ClearLedger audit archiver (PostgreSQL outbox -> S3 NDJSON)"
  package_type  = "Image"
  image_uri     = var.archiver_image
  role          = aws_iam_role.archiver.arn
  timeout       = 120
  memory_size   = 512

  environment {
    variables = merge(local.common_lambda_env, {
      DATABASE_URL         = local.database_url
      AUDIT_BUCKET         = aws_s3_bucket.audit.bucket
      AUDIT_PREFIX         = var.audit_prefix
      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.this["archiver"].name
    })
  }

  logging_config {
    log_format = "Text"
    log_group  = aws_cloudwatch_log_group.this["archiver"].name
  }

  tags = { Name = "${local.p}-audit-archiver", ImageId = var.archiver_image_id }

  depends_on = [aws_iam_role_policy.archiver]
}

resource "aws_lambda_event_source_mapping" "projector" {
  event_source_arn                   = aws_sqs_queue.main.arn
  function_name                      = aws_lambda_function.projector.arn
  enabled                            = true
  batch_size                         = 5
  maximum_batching_window_in_seconds = 0
  function_response_types            = ["ReportBatchItemFailures"]
}

############################
# EventBridge Scheduler
############################

resource "aws_scheduler_schedule" "outbox" {
  name                = "${local.p}-outbox-relay"
  description         = "Drain the ClearLedger transactional outbox every minute"
  group_name          = "default"
  state               = "ENABLED"
  schedule_expression = "rate(1 minute)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.relay.arn
    role_arn = aws_iam_role.scheduler.arn
    input    = jsonencode({ source = "scheduler", job = "outbox-relay" })

    retry_policy {
      maximum_retry_attempts       = 0
      maximum_event_age_in_seconds = 60
    }
  }
}

resource "aws_scheduler_schedule" "archive" {
  name                = "${local.p}-audit-archiver"
  description         = "Archive published ClearLedger events to S3 every five minutes"
  group_name          = "default"
  state               = "ENABLED"
  schedule_expression = "rate(5 minutes)"

  flexible_time_window {
    mode = "OFF"
  }

  target {
    arn      = aws_lambda_function.archiver.arn
    role_arn = aws_iam_role.scheduler.arn
    input    = jsonencode({ source = "scheduler", job = "audit-archiver" })

    retry_policy {
      maximum_retry_attempts       = 0
      maximum_event_age_in_seconds = 300
    }
  }
}

