kw = {}
doomed = []
while True:
    r = safe(logs.describe_log_groups, **kw) or {}
    for g in r.get("logGroups", []):
        n = g["logGroupName"]
        if "cl-base" in n:
            continue
        if any(seg == p or seg.startswith(p + "-") or seg.startswith(p + "_") for seg in n.split("/")):
